import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"附录 A：超参数速查表","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/appendix-a-hyperparams.md","filePath":"chapters/appendix-a-hyperparams.md"}'),o={name:"chapters/appendix-a-hyperparams.md"};function h(l,t,c,i,n,b){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="附录-a-超参数速查表" tabindex="-1">附录 A：超参数速查表 <a class="header-anchor" href="#附录-a-超参数速查表" aria-label="Permalink to &quot;附录 A：超参数速查表&quot;">​</a></h1><h2 id="a-1-基础训练参数" tabindex="-1">A.1 基础训练参数 <a class="header-anchor" href="#a-1-基础训练参数" aria-label="Permalink to &quot;A.1 基础训练参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td>str</td><td>必填</td><td>模型名称或路径</td></tr><tr><td><code>dataset</code></td><td>str/list</td><td>必填</td><td>数据集名称或路径</td></tr><tr><td><code>output_dir</code></td><td>str</td><td>&#39;output&#39;</td><td>输出目录</td></tr><tr><td><code>seed</code></td><td>int</td><td>42</td><td>随机种子</td></tr><tr><td><code>num_train_epochs</code></td><td>int</td><td>3</td><td>训练轮数</td></tr><tr><td><code>per_device_train_batch_size</code></td><td>int</td><td>1</td><td>训练批次大小</td></tr><tr><td><code>per_device_eval_batch_size</code></td><td>int</td><td>1</td><td>评估批次大小</td></tr></tbody></table><h2 id="a-2-学习率参数" tabindex="-1">A.2 学习率参数 <a class="header-anchor" href="#a-2-学习率参数" aria-label="Permalink to &quot;A.2 学习率参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>learning_rate</code></td><td>float</td><td>full:1e-5, lora:1e-4</td><td>学习率</td></tr><tr><td><code>lr_scheduler_type</code></td><td>str</td><td>&#39;cosine&#39;</td><td>学习率调度器</td></tr><tr><td><code>warmup_ratio</code></td><td>float</td><td>0.0</td><td>预热比例</td></tr><tr><td><code>warmup_steps</code></td><td>int</td><td>0</td><td>预热步数</td></tr><tr><td><code>weight_decay</code></td><td>float</td><td>0.0</td><td>权重衰减</td></tr><tr><td><code>max_grad_norm</code></td><td>float</td><td>1.0</td><td>梯度裁剪阈值</td></tr></tbody></table><h2 id="a-3-优化器参数" tabindex="-1">A.3 优化器参数 <a class="header-anchor" href="#a-3-优化器参数" aria-label="Permalink to &quot;A.3 优化器参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>optimizer</code></td><td>str</td><td>&#39;adamw&#39;</td><td>优化器类型</td></tr><tr><td><code>lorap_lr_ratio</code></td><td>float</td><td>2.0**4</td><td>LoRA+ 学习率比例</td></tr><tr><td><code>use_galore</code></td><td>bool</td><td>False</td><td>使用 GaLore 优化器</td></tr><tr><td><code>galore_rank</code></td><td>int</td><td>128</td><td>GaLore 秩</td></tr><tr><td><code>galore_update_proj_gap</code></td><td>int</td><td>200</td><td>GaLore 投影更新间隔</td></tr></tbody></table><h2 id="a-4-微调参数" tabindex="-1">A.4 微调参数 <a class="header-anchor" href="#a-4-微调参数" aria-label="Permalink to &quot;A.4 微调参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>tuner_type</code></td><td>str</td><td>&#39;lora&#39;</td><td>微调类型</td></tr><tr><td><code>lora_rank</code></td><td>int</td><td>8</td><td>LoRA 秩</td></tr><tr><td><code>lora_alpha</code></td><td>int</td><td>32</td><td>LoRA alpha</td></tr><tr><td><code>lora_dropout</code></td><td>float</td><td>0.05</td><td>LoRA dropout</td></tr><tr><td><code>target_modules</code></td><td>list</td><td>None</td><td>目标模块</td></tr><tr><td><code>modules_to_save</code></td><td>list</td><td>None</td><td>保留训练的模块</td></tr></tbody></table><h2 id="a-5-rlhf-通用参数" tabindex="-1">A.5 RLHF 通用参数 <a class="header-anchor" href="#a-5-rlhf-通用参数" aria-label="Permalink to &quot;A.5 RLHF 通用参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>rlhf_type</code></td><td>str</td><td>&#39;dpo&#39;</td><td>RLHF 算法类型</td></tr><tr><td><code>ref_model</code></td><td>str</td><td>None</td><td>参考模型</td></tr><tr><td><code>beta</code></td><td>float</td><td>DPO:0.1, GRPO:0.04, GKD:0.5</td><td>温度参数</td></tr><tr><td><code>label_smoothing</code></td><td>float</td><td>0.0</td><td>标签平滑</td></tr><tr><td><code>max_completion_length</code></td><td>int</td><td>512</td><td>最大生成长度</td></tr><tr><td><code>temperature</code></td><td>float</td><td>0.9</td><td>采样温度</td></tr></tbody></table><h2 id="a-6-dpo-参数" tabindex="-1">A.6 DPO 参数 <a class="header-anchor" href="#a-6-dpo-参数" aria-label="Permalink to &quot;A.6 DPO 参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>loss_type</code></td><td>list</td><td>[&#39;sigmoid&#39;]</td><td>DPO 损失类型</td></tr><tr><td><code>loss_weights</code></td><td>list</td><td>None</td><td>损失权重</td></tr><tr><td><code>rpo_alpha</code></td><td>float</td><td>None</td><td>RPO alpha 参数</td></tr><tr><td><code>ld_alpha</code></td><td>float</td><td>None</td><td>LD-DPO alpha 参数</td></tr><tr><td><code>discopop_tau</code></td><td>float</td><td>0.05</td><td>DiscoPOP tau 参数</td></tr></tbody></table><h2 id="a-7-cpo-simpo-参数" tabindex="-1">A.7 CPO/SimPO 参数 <a class="header-anchor" href="#a-7-cpo-simpo-参数" aria-label="Permalink to &quot;A.7 CPO/SimPO 参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>cpo_alpha</code></td><td>float</td><td>1.0</td><td>CPO NLL 损失权重</td></tr><tr><td><code>simpo_gamma</code></td><td>float</td><td>1.0</td><td>SimPO margin</td></tr></tbody></table><h2 id="a-8-kto-参数" tabindex="-1">A.8 KTO 参数 <a class="header-anchor" href="#a-8-kto-参数" aria-label="Permalink to &quot;A.8 KTO 参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>desirable_weight</code></td><td>float</td><td>1.0</td><td>正样本权重</td></tr><tr><td><code>undesirable_weight</code></td><td>float</td><td>1.0</td><td>负样本权重</td></tr></tbody></table><h2 id="a-9-grpo-参数" tabindex="-1">A.9 GRPO 参数 <a class="header-anchor" href="#a-9-grpo-参数" aria-label="Permalink to &quot;A.9 GRPO 参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>num_generations</code></td><td>int</td><td>8</td><td>每个 prompt 生成数</td></tr><tr><td><code>reward_funcs</code></td><td>list</td><td>[]</td><td>奖励函数列表</td></tr><tr><td><code>reward_weights</code></td><td>list</td><td>None</td><td>奖励权重</td></tr><tr><td><code>advantage_estimator</code></td><td>str</td><td>&#39;grpo&#39;</td><td>优势估计器</td></tr><tr><td><code>scale_rewards</code></td><td>str</td><td>&#39;group&#39;</td><td>奖励缩放方式</td></tr><tr><td><code>kl_in_reward</code></td><td>bool</td><td>False</td><td>是否在奖励中包含 KL</td></tr></tbody></table><h2 id="a-10-gkd-参数" tabindex="-1">A.10 GKD 参数 <a class="header-anchor" href="#a-10-gkd-参数" aria-label="Permalink to &quot;A.10 GKD 参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>teacher_model</code></td><td>str</td><td>None</td><td>教师模型</td></tr><tr><td><code>sft_alpha</code></td><td>float</td><td>0.0</td><td>SFT 损失权重</td></tr><tr><td><code>lmbda</code></td><td>float</td><td>0.5</td><td>JSD lambda 参数</td></tr><tr><td><code>gkd_logits_topk</code></td><td>int</td><td>None</td><td>仅保留 top-k logits</td></tr></tbody></table><h2 id="a-11-ppo-参数" tabindex="-1">A.11 PPO 参数 <a class="header-anchor" href="#a-11-ppo-参数" aria-label="Permalink to &quot;A.11 PPO 参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>num_ppo_epochs</code></td><td>int</td><td>4</td><td>PPO 更新轮数</td></tr><tr><td><code>kl_coef</code></td><td>float</td><td>0.05</td><td>KL 系数</td></tr><tr><td><code>vf_coef</code></td><td>float</td><td>0.1</td><td>价值函数系数</td></tr><tr><td><code>cliprange</code></td><td>float</td><td>0.2</td><td>裁剪范围</td></tr><tr><td><code>gamma</code></td><td>float</td><td>1.0</td><td>折扣因子</td></tr><tr><td><code>lam</code></td><td>float</td><td>0.95</td><td>GAE lambda</td></tr></tbody></table><h2 id="a-12-分布式训练参数" tabindex="-1">A.12 分布式训练参数 <a class="header-anchor" href="#a-12-分布式训练参数" aria-label="Permalink to &quot;A.12 分布式训练参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>deepspeed</code></td><td>str</td><td>None</td><td>DeepSpeed 配置</td></tr><tr><td><code>zero_hpz_partition_size</code></td><td>int</td><td>None</td><td>ZeRO++ 分区大小</td></tr><tr><td><code>fsdp</code></td><td>str</td><td>None</td><td>FSDP 配置</td></tr><tr><td><code>gradient_accumulation_steps</code></td><td>int</td><td>1</td><td>梯度累积步数</td></tr></tbody></table><h2 id="a-13-混合精度参数" tabindex="-1">A.13 混合精度参数 <a class="header-anchor" href="#a-13-混合精度参数" aria-label="Permalink to &quot;A.13 混合精度参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>bf16</code></td><td>bool</td><td>False</td><td>使用 bf16</td></tr><tr><td><code>fp16</code></td><td>bool</td><td>False</td><td>使用 fp16</td></tr><tr><td><code>fp16_opt_level</code></td><td>str</td><td>&#39;O1&#39;</td><td>FP16 优化级别</td></tr></tbody></table><h2 id="a-14-评估参数" tabindex="-1">A.14 评估参数 <a class="header-anchor" href="#a-14-评估参数" aria-label="Permalink to &quot;A.14 评估参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>eval_strategy</code></td><td>str</td><td>&#39;no&#39;</td><td>评估策略</td></tr><tr><td><code>eval_steps</code></td><td>int</td><td>None</td><td>评估间隔</td></tr><tr><td><code>metric_for_best_model</code></td><td>str</td><td>&#39;loss&#39;</td><td>最佳模型指标</td></tr><tr><td><code>greater_is_better</code></td><td>bool</td><td>False</td><td>指标是否越大越好</td></tr></tbody></table><h2 id="a-15-部署参数" tabindex="-1">A.15 部署参数 <a class="header-anchor" href="#a-15-部署参数" aria-label="Permalink to &quot;A.15 部署参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>infer_backend</code></td><td>str</td><td>&#39;transformers&#39;</td><td>推理后端</td></tr><tr><td><code>tensor_parallel_size</code></td><td>int</td><td>1</td><td>张量并行大小</td></tr><tr><td><code>gpu_memory_utilization</code></td><td>float</td><td>0.9</td><td>GPU 显存利用率</td></tr><tr><td><code>max_model_len</code></td><td>int</td><td>None</td><td>最大模型长度</td></tr><tr><td><code>temperature</code></td><td>float</td><td>0.7</td><td>采样温度</td></tr><tr><td><code>top_p</code></td><td>float</td><td>0.9</td><td>Top-p 采样</td></tr><tr><td><code>top_k</code></td><td>int</td><td>50</td><td>Top-k 采样</td></tr></tbody></table><h2 id="a-16-参数推荐值速查" tabindex="-1">A.16 参数推荐值速查 <a class="header-anchor" href="#a-16-参数推荐值速查" aria-label="Permalink to &quot;A.16 参数推荐值速查&quot;">​</a></h2><h3 id="学习率推荐" tabindex="-1">学习率推荐 <a class="header-anchor" href="#学习率推荐" aria-label="Permalink to &quot;学习率推荐&quot;">​</a></h3><table tabindex="0"><thead><tr><th>训练方式</th><th>推荐学习率</th></tr></thead><tbody><tr><td>full</td><td>1e-5 ~ 5e-5</td></tr><tr><td>lora</td><td>1e-4 ~ 3e-4</td></tr><tr><td>qlora</td><td>1e-4 ~ 2e-4</td></tr><tr><td>dpo</td><td>1e-6 ~ 5e-6</td></tr><tr><td>grpo</td><td>1e-6 ~ 1e-5</td></tr></tbody></table><h3 id="beta-推荐值" tabindex="-1">beta 推荐值 <a class="header-anchor" href="#beta-推荐值" aria-label="Permalink to &quot;beta 推荐值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>推荐值</th></tr></thead><tbody><tr><td>DPO</td><td>0.05 ~ 0.2</td></tr><tr><td>CPO</td><td>0.05 ~ 0.2</td></tr><tr><td>SimPO</td><td>1.0 ~ 3.0</td></tr><tr><td>ORPO</td><td>0.05 ~ 0.2</td></tr><tr><td>KTO</td><td>0.05 ~ 0.2</td></tr><tr><td>PPO</td><td>0.01 ~ 0.1</td></tr><tr><td>GRPO</td><td>0.01 ~ 0.1</td></tr><tr><td>GKD</td><td>0.3 ~ 0.7</td></tr></tbody></table><h3 id="温度推荐值" tabindex="-1">温度推荐值 <a class="header-anchor" href="#温度推荐值" aria-label="Permalink to &quot;温度推荐值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐值</th></tr></thead><tbody><tr><td>确定性任务</td><td>0.0</td></tr><tr><td>创意写作</td><td>0.9</td></tr><tr><td>代码生成</td><td>0.2</td></tr><tr><td>对话</td><td>0.7</td></tr></tbody></table>',38)])])}const _=d(o,[["render",h]]);export{p as __pageData,_ as default};
